CREATE TABLE tenants (id CHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL);
CREATE TABLE users (id CHAR(36) PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, password_hash VARCHAR(255) NOT NULL);
CREATE TABLE memberships (tenant_id CHAR(36) NOT NULL, user_id CHAR(36) NOT NULL, role VARCHAR(20) NOT NULL, PRIMARY KEY(tenant_id,user_id), FOREIGN KEY(tenant_id) REFERENCES tenants(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE sessions (token_hash CHAR(64) PRIMARY KEY, user_id CHAR(36) NOT NULL, csrf_token VARCHAR(64) NOT NULL, expires_at DATETIME(6) NOT NULL, INDEX(expires_at), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE watchlists (id CHAR(36) PRIMARY KEY, tenant_id CHAR(36) NOT NULL, sku_id VARCHAR(80) NOT NULL, target_price DECIMAL(14,2) NOT NULL, consent BOOLEAN NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME(6) NOT NULL, UNIQUE(tenant_id,id), UNIQUE(tenant_id,sku_id), FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE observations (id CHAR(36) PRIMARY KEY, tenant_id CHAR(36) NOT NULL, watch_id CHAR(36) NOT NULL, source_key VARCHAR(120) NOT NULL, amount DECIMAL(14,2) NOT NULL, currency CHAR(3) NOT NULL, observed_at DATETIME(6) NOT NULL, received_at DATETIME(6) NOT NULL, region VARCHAR(8) NOT NULL, basis VARCHAR(100) NOT NULL, synthetic BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(tenant_id,source_key), INDEX(tenant_id,watch_id,observed_at), FOREIGN KEY(tenant_id,watch_id) REFERENCES watchlists(tenant_id,id));
CREATE TABLE deal_scores (tenant_id CHAR(36) NOT NULL, watch_id CHAR(36) NOT NULL, observation_id CHAR(36) NOT NULL, status VARCHAR(20) NOT NULL, score INT NULL, change_pct DECIMAL(8,2) NULL, baseline DECIMAL(14,2) NULL, samples INT NOT NULL, explanation VARCHAR(500) NOT NULL, PRIMARY KEY(tenant_id,watch_id), FOREIGN KEY(tenant_id,watch_id) REFERENCES watchlists(tenant_id,id), FOREIGN KEY(observation_id) REFERENCES observations(id));
CREATE TABLE sync_jobs (id CHAR(36) PRIMARY KEY, tenant_id CHAR(36) NOT NULL, watch_id CHAR(36) NOT NULL, request_key VARCHAR(80) NOT NULL, scenario VARCHAR(24) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending', attempts INT NOT NULL DEFAULT 0, available_at DATETIME(6) NOT NULL, lease_until DATETIME(6) NULL, lease_token CHAR(36) NULL, last_error VARCHAR(80) NULL, created_at DATETIME(6) NOT NULL, UNIQUE(tenant_id,request_key), INDEX(status,available_at,lease_until), FOREIGN KEY(tenant_id,watch_id) REFERENCES watchlists(tenant_id,id));
CREATE TABLE outbox (id CHAR(36) PRIMARY KEY, tenant_id CHAR(36) NOT NULL, kind VARCHAR(50) NOT NULL, aggregate_id CHAR(36) NOT NULL, payload JSON NOT NULL, created_at DATETIME(6) NOT NULL, published_at DATETIME(6) NULL, INDEX(published_at,created_at));
CREATE TABLE inbox (consumer VARCHAR(50) NOT NULL, event_id CHAR(36) NOT NULL, processed_at DATETIME(6) NOT NULL, PRIMARY KEY(consumer,event_id));
CREATE TABLE alerts (id CHAR(36) PRIMARY KEY, tenant_id CHAR(36) NOT NULL, watch_id CHAR(36) NOT NULL, price_state VARCHAR(160) NOT NULL, amount DECIMAL(14,2) NOT NULL, created_at DATETIME(6) NOT NULL, UNIQUE(tenant_id,price_state), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,watch_id) REFERENCES watchlists(tenant_id,id));
CREATE TABLE notification_deliveries (id CHAR(36) PRIMARY KEY, tenant_id CHAR(36) NOT NULL, alert_id CHAR(36) NOT NULL, status VARCHAR(20) NOT NULL, delivered_at DATETIME(6) NULL, UNIQUE(tenant_id,alert_id), FOREIGN KEY(tenant_id,alert_id) REFERENCES alerts(tenant_id,id));
CREATE TABLE outbound_clicks (id CHAR(36) PRIMARY KEY, tenant_id CHAR(36) NOT NULL, watch_id CHAR(36) NOT NULL, request_key VARCHAR(80) NOT NULL, created_at DATETIME(6) NOT NULL, synthetic BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(tenant_id,request_key), FOREIGN KEY(tenant_id,watch_id) REFERENCES watchlists(tenant_id,id));
CREATE TABLE audit_logs (id CHAR(36) PRIMARY KEY, tenant_id CHAR(36) NOT NULL, actor_id CHAR(36) NULL, action VARCHAR(80) NOT NULL, resource_id CHAR(36) NULL, created_at DATETIME(6) NOT NULL, INDEX(tenant_id,created_at));
